// Объединяем статистику и записи
const stats = $('Get General Statistics').first().json;
const appointments = $('Get Tomorrow Appointments').all().map(item => item.json);

return {
  stats: stats,
  appointments: appointments
};

// Форматируем сообщение со статистикой
const data = $input.first().json;
const stats = data.stats;
const appointments = data.appointments;

// Форматируем дату завтра
const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
const tomorrowStr = tomorrow.toLocaleDateString('ru-RU', {
  weekday: 'long',
  day: '2-digit',
  month: 'long'
});

let message = `📊 *Ежедневная статистика*\n\n`;
message += `👥 Всего клиентов: ${stats.total_clients}\n`;
message += `🐾 Всего питомцев: ${stats.total_pets}\n`;
message += `📅 Предстоящих записей: ${stats.upcoming_appointments}\n`;
message += `✅ Выполнено сегодня: ${stats.today_completed}\n`;
message += `💰 Доход за месяц: ${stats.month_revenue} ₽\n\n`;

message += `📆 *Записи на завтра (${tomorrowStr})*\n`;
message += `_Всего: ${stats.tomorrow_scheduled}_\n\n`;

if (appointments.length === 0) {
  message += '✨ Записей нет';
} else {
  appointments.forEach((apt, index) => {
    const clientName = apt.last_name ? 
      `${apt.first_name} ${apt.last_name}` : 
      apt.first_name;

    message += `${index + 1}. *${apt.appointment_time}* - ${clientName}\n`;
    message += `   🐾 ${apt.pet_name} (${apt.pet_breed})\n`;
    message += `   ✂️ ${apt.service_name} - ${apt.price} ₽\n`;
    message += `   📞 ${apt.phone}\n\n`;
  });
}

return {
  message: message,
  adminId: process.env.TELEGRAM_ADMIN_ID,
  parseMode: 'Markdown'
};
